import { describe, it, expect } from "vitest";
import { loadSave, saveGame, GameSave, CURRENT_VERSION } from "./save";

const NEWER_SAVE = JSON.stringify({
  version: CURRENT_VERSION + 1, // written by a newer minor version
  gold: 100,
  level: 3,
  ext: { dlc2_pet: "rock" },
  futureFlag: true,
});

describe("forward-compatible saves", () => {
  it("preserves unknown fields byte-identically through load -> edit -> save", () => {
    const save = loadSave(NEWER_SAVE);

    // Known fields validated and readable.
    expect(save.version).toBe(CURRENT_VERSION + 1);
    expect(save.gold).toBe(100);
    expect(save.level).toBe(3);

    // Mutate a known field.
    save.gold = 250;

    const out = saveGame(save);
    const parsed = JSON.parse(out);

    // Both unknown fields survive.
    expect(parsed.futureFlag).toBe(true);
    expect(parsed.ext).toEqual({ dlc2_pet: "rock" });

    // Byte-identical reserialization of the unknown values.
    expect(JSON.stringify(parsed.ext)).toBe('{"dlc2_pet":"rock"}');
    expect(out).toContain('"futureFlag":true');

    // Stable key order for known fields; unknowns appended in original order.
    expect(Object.keys(parsed)).toEqual([
      "version",
      "gold",
      "level",
      "ext",
      "futureFlag",
    ]);
    expect(Object.keys(parsed.ext)).toEqual(["dlc2_pet"]);
    expect(out).toBe(
      '{"version":2,"gold":250,"level":3,"ext":{"dlc2_pet":"rock"},"futureFlag":true}'
    );
  });

  it("keeps unknown fields by default (stripping off)", () => {
    const out = saveGame(loadSave(NEWER_SAVE));
    const parsed = JSON.parse(out);
    expect(parsed.ext.dlc2_pet).toBe("rock");
    expect(parsed.futureFlag).toBe(true);
  });

  it("strips unknown fields when strict:true", () => {
    const out = saveGame(loadSave(NEWER_SAVE, { strict: true }));
    const parsed = JSON.parse(out);
    expect(parsed).toEqual({ version: 2, gold: 100, level: 3 });
    expect("ext" in parsed).toBe(false);
    expect("futureFlag" in parsed).toBe(false);
  });

  it("preserves multiple unknowns in original order, including ext entries", () => {
    const src = JSON.stringify({
      futureZ: [1, { deep: true }],
      version: 2,
      alpha: "first",
      gold: 5,
      level: 1,
      ext: { b: 2, a: 1 },
    });
    const parsed = JSON.parse(saveGame(loadSave(src)));
    expect(Object.keys(parsed)).toEqual([
      "version",
      "gold",
      "level",
      "futureZ",
      "alpha",
    ]);
    expect(JSON.stringify(parsed.ext ?? null)).toBeNull(); // ext is not top-level unknown
    expect((parsed as any).futureZ).toEqual([1, { deep: true }]);
  });

  it("supports reading and writing extension fields via the ext bag", () => {
    const save = loadSave(NEWER_SAVE);
    expect(save.getExt("dlc2_pet")).toBe("rock");
    save.setExt("dlc2_pet", "stone");
    save.setExt("new_thing", { ok: 1 });
    const parsed = JSON.parse(saveGame(save));
    expect(parsed.ext).toEqual({ dlc2_pet: "stone", new_thing: { ok: 1 } });
  });

  it("validates known fields on load", () => {
    expect(() => loadSave('{"version":"x","gold":1,"level":1}')).toThrow(TypeError);
    expect(() => loadSave('{"version":0,"gold":1,"level":1}')).toThrow(TypeError);
    expect(() => loadSave('{"version":1,"gold":"lots","level":1}')).toThrow(TypeError);
    expect(() => loadSave('{"version":1,"gold":NaN,"level":1}')).toThrow(SyntaxError);
    expect(() => loadSave("[1,2,3]")).toThrow(TypeError);
    expect(() => loadSave("{not json")).toThrow(SyntaxError);
  });

  it("validates known fields on mutation", () => {
    const save = loadSave(NEWER_SAVE);
    expect(() => (save.gold = NaN)).toThrow(TypeError);
    expect(() => (save.level = "high" as unknown as number)).toThrow(TypeError);
    // Untouched after failed assignments.
    expect(save.gold).toBe(100);
  });
});

