/**
 * Forward-compatible JSON save loading/saving.
 *
 * - Known fields are validated on load.
 * - Unknown top-level fields and all fields nested under `ext` are
 *   preserved verbatim through a load -> edit -> save cycle.
 * - Serialization order: known fields first (stable key order),
 *   then unknowns appended in their original order (`ext` keeps its
 *   original position; its entries keep their original order).
 * - By default unknown fields are kept; `strict: true` strips them.
 */

export const CURRENT_VERSION = 1;

/** Known top-level fields, in canonical serialization order. */
const KNOWN_FIELDS = ["version", "gold", "level"] as const;

export interface SaveSchema {
  version: number;
  gold: number;
  level: number;
}

interface UnknownEntry {
  key: string;
  value: unknown;
}

/** A preserved `ext` bag pinned at its original top-level position. */
interface ExtBag {
  key: "ext";
  entries: UnknownEntry[];
}

type PreservedEntry = UnknownEntry | ExtBag;

function isExtBag(e: PreservedEntry): e is ExtBag {
  return e.key === "ext" && Array.isArray((e as ExtBag).entries);
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

function assertFiniteNumber(name: string, v: unknown): void {
  if (typeof v !== "number" || !Number.isFinite(v)) {
    throw new TypeError(
      `Invalid save: field "${name}" must be a finite number, got ${JSON.stringify(v)}`
    );
  }
}

export class GameSave {
  /** @internal Preserved unknowns, in original order (`ext` included as a bag). */
  private readonly preserved: PreservedEntry[];

  /** @internal Use {@link loadSave} to construct. */
  constructor(
    public schema: SaveSchema,
    preserved: PreservedEntry[]
  ) {
    this.preserved = preserved;
  }

  get version(): number {
    return this.schema.version;
  }

  get gold(): number {
    return this.schema.gold;
  }

  set gold(v: number) {
    assertFiniteNumber("gold", v);
    this.schema.gold = v;
  }

  get level(): number {
    return this.schema.level;
  }

  set level(v: number) {
    assertFiniteNumber("level", v);
    this.schema.level = v;
  }

  private findExtBag(): ExtBag | undefined {
    return this.preserved.find(isExtBag);
  }

  /** Read a preserved extension field. */
  getExt(key: string): unknown {
    const bag = this.findExtBag();
    if (!bag) return undefined;
    const entry = bag.entries.find((e) => e.key === key);
    return entry ? entry.value : undefined;
  }

  /** Add or update an extension field (appended at the end if new). */
  setExt(key: string, value: unknown): void {
    let bag = this.findExtBag();
    if (!bag) {
      bag = { key: "ext", entries: [] };
      this.preserved.push(bag);
    }
    const entry = bag.entries.find((e) => e.key === key);
    if (entry) entry.value = value;
    else bag.entries.push({ key, value });
  }

  /**
   * Serialize: known fields in stable order, then preserved unknown
   * top-level fields in their original order (`ext` reconstructed at
   * its original position, entries in original order).
   */
  serialize(): string {
    const out: Record<string, unknown> = {};
    // Known fields, stable order.
    for (const k of KNOWN_FIELDS) {
      out[k] = this.schema[k];
    }
    // Preserved unknowns, original order.
    for (const entry of this.preserved) {
      if (isExtBag(entry)) {
        const ext: Record<string, unknown> = {};
        for (const { key, value } of entry.entries) {
          ext[key] = value;
        }
        out["ext"] = ext;
      } else {
        out[entry.key] = entry.value;
      }
    }
    return JSON.stringify(out);
  }
}

export interface LoadOptions {
  /**
   * When true, unknown top-level fields and `ext` entries are stripped
   * instead of preserved. Off by default.
   */
  strict?: boolean;
}

/**
 * Load a save from JSON text. Known fields are validated; unknown
 * top-level fields and everything under `ext` are captured verbatim so
 * they survive a subsequent {@link GameSave.serialize}.
 *
 * Saves written by newer minor versions load fine: their extra fields
 * are simply carried along untouched.
 */
export function loadSave(text: string, options: LoadOptions = {}): GameSave {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    throw new SyntaxError(`Invalid save: not valid JSON (${(e as Error).message})`);
  }
  if (!isPlainObject(parsed)) {
    throw new TypeError("Invalid save: expected a JSON object at the top level");
  }

  // --- Validate known fields ---
  if (
    typeof parsed.version !== "number" ||
    !Number.isInteger(parsed.version) ||
    parsed.version < 1
  ) {
    throw new TypeError(
      `Invalid save: field "version" must be a positive integer, got ${JSON.stringify(parsed.version)}`
    );
  }
  assertFiniteNumber("gold", parsed.gold);
  assertFiniteNumber("level", parsed.level);

  const schema: SaveSchema = {
    version: parsed.version,
    gold: parsed.gold,
    level: parsed.level,
  };

  const strict = options.strict === true;
  if (strict) return new GameSave(schema, []);

  // --- Capture unknowns verbatim, in original order ---
  const preserved: PreservedEntry[] = [];
  for (const key of Object.keys(parsed)) {
    if ((KNOWN_FIELDS as readonly string[]).includes(key)) continue;
    if (key === "ext" && isPlainObject(parsed.ext)) {
      const entries: UnknownEntry[] = Object.keys(parsed.ext).map((k) => ({
        key: k,
        value: parsed.ext[k],
      }));
      preserved.push({ key: "ext", entries });
      continue;
    }
    preserved.push({ key, value: parsed[key] });
  }

  return new GameSave(schema, preserved);
}

/** Convenience alias. */
export function saveGame(save: GameSave): string {
  return save.serialize();
}

